/// Look up an operation by HTTP method and documented path.
pub fn find(method: &str, path: &str) -> Option<&'static Op> {
    OPS.iter().find(|op| op.method == method && op.path == path)
}

/// Every tag used by the specification, with its operation count.
#[cfg(test)]
pub fn tag_counts() -> Vec<(&'static str, usize)> {
    let mut out: Vec<(&'static str, usize)> = Vec::new();
    for op in OPS {
        match out.iter_mut().find(|(t, _)| *t == op.tag) {
            Some(entry) => entry.1 += 1,
            None => out.push((op.tag, 1)),
        }
    }
    out.sort_by_key(|(_, count)| std::cmp::Reverse(*count));
    out
}
